def get_all_vocabulary_topics():
    return VOCABULARY_CATALOG

def get_vocabulary_topic_by_id(topic_id: str):
    for t in VOCABULARY_CATALOG:
        if t.get('id') == topic_id or t.get('topic', '').lower() == str(topic_id).lower():
            return t
    return VOCABULARY_CATALOG[0] if VOCABULARY_CATALOG else None
